'use strict';

// MODULES //

var ack = require( './ack' );
var app = require( './app' );
var events = require( './events' );
var home = require( './home' );
var landing = require( './landing' );
var ping = require( './ping' );
var spec = require( './spec' );
var status = require( './status' ); // eslint-disable-line stdlib/no-redeclare

var lilgui = require( './vendored/lilgui' );
var vega = require( './vendored/vega' );

var background = require( './config/background' );
var description = require( './config/description' );
var height = require( './config/height' );
var paddingBottom = require( './config/padding/bottom' );
var paddingLeft = require( './config/padding/left' );
var paddingRight = require( './config/padding/right' );
var paddingTop = require( './config/padding/top' );
var titleText = require( './config/title/text' );
var width = require( './config/width' );


// MAIN //

/**
* Registers routes.
*
* @private
* @param {Object} router - router instance
*/
function register( router ) {
	// Status routes:
	router.route( status() );           // /status
	router.route( ping() );             // /ping

	// Static files:
	router.route( vega() );             // /vendored/vega.min.js
	router.route( lilgui() );           // /vendored/lil_gui.min.js
	router.route( app() );              // /app.js

	// Landing page:
	router.route( home() );             // /
	router.route( landing() );          // /index.html

	// Server-sent events:
	router.route( events() );           // /events
	router.route( ack() );              // /ack

	// Specification:
	router.route( spec() );             // /spec

	router.route( background() );       // /config/background

	router.route( description() );      // /config/description

	router.route( height() );           // /config/height

	router.route( paddingBottom() );    // /config/padding/bottom
	router.route( paddingLeft() );      // /config/padding/left
	router.route( paddingRight() );     // /config/padding/right
	router.route( paddingTop() );       // /config/padding/top

	router.route( titleText() );        // /config/title/text

	router.route( width() );            // /config/width
}


// EXPORTS //

module.exports = register;
